// План specs/job-assignment.md 2.1 / 2.2 (#cacd64, тот же коммит что #c9f0f5 и #126f07). PROD, admin, компания «test», десктоп, EN.
// @writes @data: назначает/снимает QA-Tech Alpha (без согласия на SMS — «No SMS», SMS не уходит) на постоянной работе «QA-AUTO 04d33a job»;
// в конце работа остаётся Submitted без техника. Если включён «Allow Multiple Techs» — пропуск (настройку не переключаем).
// Источник: «מה רצוי» — אחרי שינוי שיבוץ בדף העבודה, רשימת Jobs מציגה מיד את המצב העדכני (העבודה בלשונית ועם הטכנאי הנכונים), בלי רענון ידני.
// Факты 17.11: 9/9 + 2 при медленной сети 3G, устаревших кадров 0. Переход в Jobs — кликом по меню (SPA), БЕЗ перезагрузки и без ожидания сохранения.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, prepare, readMultiTech } from '../multi-tech-assignment/multi-tech-helpers';
import {
  ALPHA, acceptLeaveDialogs, assignTech, ensureNoTechnician, expectLatestHistory, expectTechnician, jobRow, openQaJob, takeOffButton,
} from './assignment-helpers';

test.use({ storageState: ADMIN_STATE });

async function goToJobsViaMenu(page: import('@playwright/test').Page) {
  await page.getByRole('link', { name: 'Jobs', exact: true }).filter({ visible: true }).first().click();
  await page.waitForURL(/\/jobs/i);
}

async function search(page: import('@playwright/test').Page, jobId: string) {
  await page.getByPlaceholder(/^Search jobs/i).fill(jobId);
}

test.describe('Jobs list shows the fresh assignment right after leaving the job page (#cacd64)', () => {
  test('Take the technician off (X) and go to Jobs at once: the job is in Submitted, not in Assigned #cacd64 @desktop @writes @data', async ({ page }) => {
    test.setTimeout(180_000);
    await prepare(page, 'en');
    acceptLeaveDialogs(page);
    test.skip(await readMultiTech(page), '«Allow Multiple Techs» = ON — сценарий для OFF');
    const { url, jobId } = await openQaJob(page);
    try {
      await page.goto(url);
      await ensureNoTechnician(page);
      await assignTech(page, ALPHA);
      await expectLatestHistory(page, `Assigned to ${ALPHA}`);
      await expectTechnician(page, ALPHA);

      // X и сразу Jobs (без ожидания строки истории)
      await takeOffButton(page, ALPHA).click();
      await goToJobsViaMenu(page);
      await search(page, jobId);
      await page.getByRole('tab', { name: 'Submitted', exact: true }).click();
      await expect(jobRow(page, jobId), 'работа без техника сразу в Submitted').toBeVisible({ timeout: 10_000 });
      await page.getByRole('tab', { name: 'Assigned', exact: true }).click();
      await expect(jobRow(page, jobId), 'в Assigned её нет').toHaveCount(0, { timeout: 10_000 });
    } finally {
      await page.goto(url).catch(() => {});
      await ensureNoTechnician(page).catch(() => {});
    }
  });

  test('Assign a technician and go to Jobs at once: the job is in Assigned with that technician #cacd64 @desktop @writes @data', async ({ page }) => {
    test.setTimeout(180_000);
    await prepare(page, 'en');
    acceptLeaveDialogs(page);
    test.skip(await readMultiTech(page), '«Allow Multiple Techs» = ON — сценарий для OFF');
    const { url, jobId } = await openQaJob(page);
    try {
      await page.goto(url);
      await ensureNoTechnician(page);
      await assignTech(page, ALPHA);
      await goToJobsViaMenu(page);
      await search(page, jobId);
      await page.getByRole('tab', { name: 'Assigned', exact: true }).click();
      await expect(jobRow(page, jobId), 'работа сразу в Assigned').toBeVisible({ timeout: 10_000 });
      await expect(jobRow(page, jobId)).toContainText(ALPHA);
    } finally {
      await page.goto(url).catch(() => {});
      await ensureNoTechnician(page).catch(() => {});
    }
  });
});
